def first_unique_char(text):
    """Return the first character that appears exactly once in text, or None if no such character exists."""
    if not text:
        return None

    word_counts = collections.Counter(text)

    for char in word_counts:
        count = word_counts[char]
        if count == 1:
            return char

    return None
