def first_unique_char(text: str) -> str | None:
    """Return the first character that appears exactly once in text, or None if no such character exists."""
    if len(text) == 0:
        return None
    char_counts: dict = {}
    for ch in text:
        char_counts[ch] = char_counts.get(ch, 0) + 1
    first_char = None
    for ch, count in char_counts.items():
        if count == 1:
            first_char = ch
            break
    return first_char

